"use strict";(self.webpackChunkheidelbergman_site=self.webpackChunkheidelbergman_site||[]).push([[673],{7994:e=>{e.exports=JSON.parse('[{"id":"/2026/10/29/save-the-date","metadata":{"permalink":"/blog/2026/10/29/save-the-date","source":"@site/blog/2026-10-29-save-the-date.md","title":"Save the Date - Heidelberg Triathlon 2027","description":"Save the Date: Heidelberg Triathlon am 25.07.2027","date":"2026-10-29T00:00:00.000Z","formattedDate":"29. Oktober 2026","tags":[],"hasTruncateMarker":false,"authors":[{"name":"Orga Team","title":"Heidelberg-Triathlon Orga Team","imageURL":"https://www.heidelberg-triathlon.de/img/logo/HDtri_round_mini.png","key":"orga"}],"frontMatter":{"title":"Save the Date - Heidelberg Triathlon 2027","authors":["orga"]},"unlisted":false,"nextItem":{"title":"Unsere Champions des Heidelberg Triathlon 2026","permalink":"/blog/2026/07/31/champions"}},"content":"![Save the Date: Heidelberg Triathlon am 25.07.2027](/blog/2026_10_29_save_the_date.webp)\\n\\n\u26a0\ufe0f UNSER TERMIN STEHT FEST! \u26a0\ufe0f\\n\\nDer Heidelberg Triathlon findet auch im n\xe4chsten Jahr wieder statt - und zwar am **25.07.2027**.\\n\\nMarkiert euch den Termin im Kalender, egal ob ihr als Einzel- oder Staffelstarter*in, mit der Family beim Nikar4Kids Lauf, als Helfer*in oder Support an der Strecke dabei sein wollt! Wir freuen uns auf jede*n einzelne*n von euch \ud83e\udd73\\n\\nDie Anmeldung startet wie immer am **01. Januar um 10 Uhr**. Schnell sein lohnt sich, die Pl\xe4tze sind erfahrungsgem\xe4\xdf schnell weg \ud83c\udf40"},{"id":"/2026/07/31/champions","metadata":{"permalink":"/blog/2026/07/31/champions","source":"@site/blog/2026-07-31-champions.md","title":"Unsere Champions des Heidelberg Triathlon 2026","description":"Die Champions des Heidelberg Triathlon 2026 auf dem Siegerpodest","date":"2026-07-31T00:00:00.000Z","formattedDate":"31. Juli 2026","tags":[],"hasTruncateMarker":false,"authors":[{"name":"Orga Team","title":"Heidelberg-Triathlon Orga Team","imageURL":"https://www.heidelberg-triathlon.de/img/logo/HDtri_round_mini.png","key":"orga"}],"frontMatter":{"title":"Unsere Champions des Heidelberg Triathlon 2026","authors":["orga"]},"unlisted":false,"prevItem":{"title":"Save the Date - Heidelberg Triathlon 2027","permalink":"/blog/2026/10/29/save-the-date"},"nextItem":{"title":"Strecken-Sperrungen Heidelberg Triathlon 2026","permalink":"/blog/2026/07/23/strecken-sperrungen"}},"content":"![Die Champions des Heidelberg Triathlon 2026 auf dem Siegerpodest](/blog/2026_07_31_champions_cover.webp)\\n\\nUnsere Champions des #heidelbergtriathlon2026: Valerie Moser und Jakob Breinlinger \ud83c\udfc6\\n\\n\ud83e\udd47Valerie (Karlsruher Lemminge) gewinnt auch dieses Jahr mit einer herausragenden Leistung (2:24:08) den Heidelberg Triathlon und macht damit den Titel Hattrick komplett! \ud83e\udd2f\\nNach einem starken Schwimmen landet Antonia Milowsky (Team Dietrich, 2:26:29) auf Platz 2 \ud83e\udd48und Eva Estler (Meypost SV T\xfcbingen, 2:29:52) wird Dritte \ud83e\udd49.\\nSchnellste am Berg ist Laetitia Bury (Soprema Team) \ud83d\udeb4\u200d\u2640\ufe0f\ud83d\udc51\\n\\n\ud83e\udd47Jakob (Team Nikar Heidelberg / Aera Sports Team, 2:06:38) verteidigt mit einem Start-Ziel-Sieg seinen Titel von 2025 und steht damit schon zum vierten Mal auf dem Podium des Heidelberg Triathlon! Er holt sich ebenso erneut die Bergsprintwertung \ud83d\udeb4\ud83d\udc51\\nDas Podium komplettieren Tom Holzmann auf Platz 2 \ud83e\udd48(LLG Wonnegau, 2:08:58) und Samuel M\xf6hler auf Platz 3 \ud83e\udd49 (Karlsruher Lemminge, 2:12:52).\\n\\nIn der baden-w\xfcrttembergischen Meisterschaft auf der olympischen Distanz stehen Valerie und Jakob ebenfalls ganz oben auf dem Treppchen und sind somit Landes-Meisterin und Meister! \ud83c\udfc5\\n\\nHerzlichen Gl\xfcckwunsch, ihr habt mal wieder eine krasse Leistung abgeliefert! Wir freuen uns, wenn ihr 2027 auch wieder dabei seid \u2764\ufe0f\\n\\nWir bedanken uns au\xdferdem ganz herzlich bei unseren Sponsoren f\xfcr die gro\xdfz\xfcgige Bereitstellung der Siegerpreise. \ud83c\udf81\\n\\n\ud83d\udcf82-3: @sportograf , 1: O. M\xf6hler\\n\\n![Valerie Moser beim Zieleinlauf des Heidelberg Triathlon 2026](/blog/2026_07_31_champions_1.webp)\\n\\n![Jakob Breinlinger beim Zieleinlauf des Heidelberg Triathlon 2026](/blog/2026_07_31_champions_2.webp)"},{"id":"/2026/07/23/strecken-sperrungen","metadata":{"permalink":"/blog/2026/07/23/strecken-sperrungen","source":"@site/blog/2026-07-23-strecken-sperrungen.md","title":"Strecken-Sperrungen Heidelberg Triathlon 2026","description":"Strecken-Sperrungen Heidelberg Triathlon 2026","date":"2026-07-23T00:00:00.000Z","formattedDate":"23. Juli 2026","tags":[],"hasTruncateMarker":false,"authors":[{"name":"Orga Team","title":"Heidelberg-Triathlon Orga Team","imageURL":"https://www.heidelberg-triathlon.de/img/logo/HDtri_round_mini.png","key":"orga"}],"frontMatter":{"title":"Strecken-Sperrungen Heidelberg Triathlon 2026","authors":["orga"]},"unlisted":false,"prevItem":{"title":"Unsere Champions des Heidelberg Triathlon 2026","permalink":"/blog/2026/07/31/champions"},"nextItem":{"title":"TauschZone beim Heidelberg Triathlon 2026","permalink":"/blog/2026/07/20/tauschzone"}},"content":"![Strecken-Sperrungen Heidelberg Triathlon 2026](/blog/2026_07_23_sperrungen_cover.png)\\n\\nLiebe Athlet\\\\*innen, liebe Zuschauer\\\\*innen, liebe Anwohner\\\\*innen,\\n\\nam Sonntag, den **26.07.2026**, findet der Heidelberg Triathlon statt. Wir freuen uns auf ein gro\xdfes Event und viele Zuschauer\\\\*innen. Damit der Wettkampf f\xfcr alle Beteiligten reibungslos abl\xe4uft, bitten wir um Verst\xe4ndnis f\xfcr die notwendigen Strecken-Sperrungen. Im Folgenden findet Ihr eine \xdcbersicht \xfcber die Sperrungen der einzelnen Disziplinen.\\n\\n## Schwimmen \u2014 Stra\xdfensperrungen 8:00 \u2013 10:30 Uhr\\n\\n- **Sperrung der B37** im Bereich zwischen Theodor-Heuss-Br\xfccke & Karlstor\\n- Aufhebung der Sperrung West-Ost ab ca. 10:15 Uhr\\n- Aufhebung der Sperrung Ost-West ab ca. 10:30 Uhr\\n- **Umleitung** \xfcber Schlossbergtunnel\\n\\n## Radfahren \u2014 Stra\xdfensperrungen 6:00 \u2013 14:00 Uhr\\n\\n- **L534** in Richtung Heidelberg von 8:00 Uhr bis ca. 14:00 Uhr gesperrt\\n- **Ziegelh\xe4user & Neuenheimer Landstra\xdfe** von 8:00 Uhr bis 14:00 Uhr beidseitig gesperrt\\n- **Uferstra\xdfe** ab 6:00 Uhr beidseitig gesperrt\\n- **Alte Br\xfccke** auf den seitlichen Gehwegen eingeschr\xe4nkt \xfcberquerbar\\n- **Keine Zufahrt zum K\xf6nigstuhl** von Gaiberg & Waldhilsbach ab 7:00 Uhr bis 13:00 Uhr\\n- **Keine Zufahrt zum Schloss & K\xf6nigstuhl** \xfcber Klingenteichstra\xdfe & Schloss-Wolfsbrunnenweg ab 8:30 Uhr\\n- **Achtung: Strecke f\xfchrt durch Altstadt!**\\n\\n## Laufen \u2014 Stra\xdfensperrungen 6:00 \u2013 14:00 Uhr\\n\\n- **Uferstra\xdfe** ab 6:00 Uhr beidseitig gesperrt\\n- **Br\xfcckenkopfstra\xdfe** ab 9:00 Uhr bis ca. 14:00 Uhr beidseitig gesperrt\\n- **Bergstra\xdfe** ab 9:00 Uhr bis 14:00 Uhr zwischen Br\xfcckenkopfstra\xdfe und Eingang Philosophenweg gesperrt\\n- **Philosophenweg** ab 9:00 Uhr bis 14:00 Uhr gesperrt\\n- Philosophenweg fu\xdfl\xe4ufig \xfcber Albert-\xdcberle-Str. & Schlangenweg erreichbar\\n\\n**Vielen Dank f\xfcr Eure R\xfccksichtnahme & Euer Verst\xe4ndnis!**\\n\\n![Sperrungen Schwimmen](/blog/2026_07_23_sperrungen_schwimmen.png)\\n\\n![Sperrungen Radfahren](/blog/2026_07_23_sperrungen_rad.png)\\n\\n![Sperrungen Laufen](/blog/2026_07_23_sperrungen_laufen.png)"}]')}}]);